    Integrates with CodeEfficiencyAnalyzer for task optimization insights.
    """

    def __init__(self, efficiency_analyzer: CodeEfficiencyAnalyzer = None):
        self.tasks = {}  # task_id -> task_data
        self.dependencies = {}  # task_id -> set of prerequisite task_ids
        self.efficiency_analyzer = efficiency_analyzer
        self.subscribers = []  # for real-time updates

    def add_task(self, task_id: str, title: str, priority: int = 1, due_date: str = None, 
                 code_snippet: str = None, depends_on: list = None):
        """Add a new task to the tracker."""
        self.tasks[task_id] = {
            "title": title,
            "priority": priority,
            "due_date": due_date,
            "status": "pending",
            "code_snippet": code_snippet,
            "efficiency_analysis": None
        }
        if depends_on:
            self.dependencies[task_id] = set(depends_on)
        else:
            self.dependencies[task_id] = set()

        # If code snippet provided, run efficiency analysis
        if code_snippet and self.efficiency_analyzer:
            self.tasks[task_id]["efficiency_analysis"] = self.efficiency_analyzer.analyze(code_snippet)

        self._notify("task_added", task_id)

    def update_task_status(self, task_id: str, status: str):
        """Update task status (e.g., pending, in_progress, completed)."""
        if task_id in self.tasks:
            self.tasks[task_id]["status"] = status
            self._notify("task_updated", task_id)

    def get_task_dependencies(self, task_id: str) -> list:
        """Return list of tasks that must be completed before this task."""
        return list(self.dependencies.get(task_id, []))

    def get_ready_tasks(self) -> list:
        """Return tasks whose dependencies are all completed."""
        ready = []
        for tid, deps in self.dependencies.items():
            if all(self.tasks.get(dep, {}).get("status") == "completed" for dep in deps):
                if self.tasks[tid]["status"] == "pending":
                    ready.append(tid)
        return ready

    def subscribe(self, callback):
        """Register a callback for real-time updates."""
        self.subscribers.append(callback)

    def _notify(self, event: str, task_id: str):
        """Send notifications to subscribers."""
        for sub in self.subscribers:
            sub({"event": event, "task_id": task_id, "task": self.tasks.get(task_id)})


