class CodeEfficiencyAnalyzer:
    """Analyzes code snippets for time/space complexity and algorithmic inefficiencies."""

    # Known complexity patterns (simplified heuristics)
    LOOP_COMPLEXITY = "O(n)"
    NESTED_LOOP_COMPLEXITY = "O(n^2)"
    LOG_N_COMPLEXITY = "O(log n)"
    N_LOG_N_COMPLEXITY = "O(n log n)"
    EXPONENTIAL = "O(2^n)"
    FACTORIAL = "O(n!)"

    def __init__(self):
        self.recommendations = []

    def analyze(self, code_snippet: str) -> Dict[str, Any]:
        """Analyze a code snippet and return complexity estimates and optimization recommendations."""
        self.recommendations = []

        # Heuristic-based analysis (simplified for demonstration)
        complexity = self._estimate_complexity(code_snippet)
        space_complexity = self._estimate_space_complexity(code_snippet)
        inefficiencies = self._detect_inefficiencies(code_snippet)

        # Generate recommendations
        for inefficiency in inefficiencies:
            self.recommendations.append(self._generate_recommendation(inefficiency))

        return {
            "time_complexity": complexity,
            "space_complexity": space_complexity,
            "inefficiencies": inefficiencies,
            "recommendations": self.recommendations
        }

    def _estimate_complexity(self, code: str) -> str:
        # Count loops and nesting
        loop_count = code.count("for ") + code.count("while ")
        nesting_depth = self._calculate_nesting_depth(code)

        if loop_count == 0:
            return "O(1)"
        elif nesting_depth == 1:
            return self.LOOP_COMPLEXITY
        elif nesting_depth == 2:
            return self.NESTED_LOOP_COMPLEXITY
        elif "sort()" in code or "sorted(" in code:
            return self.N_LOG_N_COMPLEXITY
        elif "**" in code or "pow(" in code:
            return self.EXPONENTIAL
        else:
            return self.LOOP_COMPLEXITY

    def _estimate_space_complexity(self, code: str) -> str:
        # Heuristic: check for list/dict comprehensions, large data structures
        if "[x for x in" in code or "{x for x in" in code:
            return "O(n)"
        elif "[[0]*n for _ in range(n)]" in code:
            return "O(n^2)"
        elif "dict()" in code or "{}" in code:
            return "O(n)"
        else:
            return "O(1)"

    def _calculate_nesting_depth(self, code: str) -> int:
        max_depth = 0
        current_depth = 0
        in_string = False
        escape = False

        for char in code:
            if escape:
                escape = False
                continue
            if char == '\\':
                escape = True
                continue
            if char == '"' or char == "'":
                in_string = not in_string
            if not in_string:
                if char in ("(", "[", "{"):
                    current_depth += 1
                    max_depth = max(max_depth, current_depth)
                elif char in (")", "]", "}"):
                    current_depth = max(0, current_depth - 1)

        return max_depth

    def _detect_inefficiencies(self, code: str) -> List[str]:
        inefficiencies = []

        # Detect common anti-patterns
        if "for i in range(len(" in code:
            inefficiencies.append("Use enumerate() instead of range(len())")
        if "list.append()" in code and "for" in code and "if" in code:
            inefficiencies.append("Consider list comprehension for simple filtering/transforming")
        if "in list" in code:
            inefficiencies.append("Use set for O(1) membership checks instead of list")
        if "sorted(" in code and "for" in code:
            inefficiencies.append("Avoid sorting inside loops; sort once outside if possible")
        if "** 2" in code:
            inefficiencies.append("Use x * x instead of x ** 2 for squaring")

        return inefficiencies

    def _generate_recommendation(self, inefficiency: str) -> Dict[str, str]:
        return {
            "type": "efficiency",
            "issue": inefficiency,
            "suggestion": self._get_suggestion(inefficiency),
            "priority": "medium" if "consider" in inefficiency.lower() else "high"
        }

    def _get_suggestion(self, issue: str) -> str:
        suggestions = {
            "Use enumerate() instead of range(len())": "Replace `for i in range(len(items))` with `for i, item in enumerate(items)`",
            "Consider list comprehension for simple filtering/transforming": "Use `[x for x in items if condition]` instead of append in loop",
            "Use set for O(1) membership checks instead of list": "Convert list to set before membership checks: `s = set(items); if x in s`",
            "Avoid sorting inside loops; sort once outside if possible": "Move `sorted()` outside loops; sort once and reuse",
            "Use x * x instead of x ** 2 for squaring": "Arithmetic multiplication is faster than exponentiation for small integer powers"
        }
        return suggestions.get(issue, "Review and refactor for better performance")


